-- Industrial Reliability & Energy Analytics
-- Synthetic data | Generated 2026-08-22
-- PostgreSQL-compatible

CREATE TABLE "DIM_MAQUINA" ("id_maquina" TEXT, "maquina" TEXT, "processo" TEXT, "tipo_equipamento" TEXT, "criticidade" TEXT, "capacidade_h" INTEGER, "potencia_kw" INTEGER, "ano_fabricacao" INTEGER, "valor_reposicao" INTEGER, "linha" TEXT, PRIMARY KEY ("id_maquina"));
CREATE TABLE "DIM_CAUSA_RAIZ" ("id_causa" TEXT, "causa_raiz" TEXT, "categoria" TEXT, "descricao" TEXT, PRIMARY KEY ("id_causa"));
CREATE TABLE "FAT_MANUTENCAO" ("id_os" TEXT, "id_maquina" TEXT, "data_inicio" TEXT, "hora_falha" TEXT, "tipo_manut" TEXT, "falha" TEXT, "componente" TEXT, "id_causa" TEXT, "tempo_diagnostico_min" INTEGER, "tempo_espera_peca_min" INTEGER, "tempo_reparo_min" NUMERIC(18,4), "tempo_teste_min" INTEGER, "tempo_parada_min" NUMERIC(18,4), "custo_mao_obra" INTEGER, "custo_pecas" INTEGER, "quantidade_producao_perdida" INTEGER, "custo_perda_producao" NUMERIC(18,4), "custo_total_os" NUMERIC(18,4), "impacto_producao" TEXT, PRIMARY KEY ("id_os"));
CREATE TABLE "FAT_PRODUCAO" ("id_producao" TEXT, "data" TEXT, "id_maquina" TEXT, "turno" INTEGER, "produto" TEXT, "plano_producao" INTEGER, "producao_real" INTEGER, "pecas_boas" INTEGER, "refugo" INTEGER, "horas_operacao" NUMERIC(18,4), "horas_parada" NUMERIC(18,4), "performance" NUMERIC(18,4), "qualidade" NUMERIC(18,4), "oee" NUMERIC(18,4), PRIMARY KEY ("id_producao"));
CREATE TABLE "FAT_ENERGIA" ("id_energia" TEXT, "data" TEXT, "id_maquina" TEXT, "turno" INTEGER, "kwh" NUMERIC(18,4), "horas_ligada" NUMERIC(18,4), "producao" INTEGER, "kwh_por_peca" NUMERIC(18,4), "custo_energia" NUMERIC(18,4), PRIMARY KEY ("id_energia"));
CREATE TABLE "FAT_PROCESSO" ("id_processo" TEXT, "data" TEXT, "id_maquina" TEXT, "turno" INTEGER, "temperatura" NUMERIC(18,4), "pressao" NUMERIC(18,4), "corrente_a" NUMERIC(18,4), "carga_pct" NUMERIC(18,4), "velocidade_pct" NUMERIC(18,4), "vibracao_mm_s" NUMERIC(18,4), "status_processo" TEXT, PRIMARY KEY ("id_processo"));
CREATE TABLE "FAT_PERDAS" ("id_perda" TEXT, "data" TEXT, "id_maquina" TEXT, "tipo_perda" TEXT, "quantidade" INTEGER, "horas" NUMERIC(18,4), "custo_unitario" NUMERIC(18,4), "custo_total" NUMERIC(18,4), PRIMARY KEY ("id_perda"));
CREATE TABLE "FAT_ACAO_MELHORIA" ("id_acao" TEXT, "id_maquina" TEXT, "id_causa" TEXT, "data" TEXT, "acao" TEXT, "responsavel" TEXT, "custo_acao" NUMERIC(18,4), "status" TEXT, "resultado" TEXT, PRIMARY KEY ("id_acao"));
ALTER TABLE "FAT_MANUTENCAO" ADD CONSTRAINT fk_manut_maquina FOREIGN KEY ("id_maquina") REFERENCES "DIM_MAQUINA" ("id_maquina");
ALTER TABLE "FAT_MANUTENCAO" ADD CONSTRAINT fk_manut_causa FOREIGN KEY ("id_causa") REFERENCES "DIM_CAUSA_RAIZ" ("id_causa");
ALTER TABLE "FAT_PRODUCAO" ADD CONSTRAINT fk_prod_maquina FOREIGN KEY ("id_maquina") REFERENCES "DIM_MAQUINA" ("id_maquina");
ALTER TABLE "FAT_ENERGIA" ADD CONSTRAINT fk_energia_maquina FOREIGN KEY ("id_maquina") REFERENCES "DIM_MAQUINA" ("id_maquina");
ALTER TABLE "FAT_PROCESSO" ADD CONSTRAINT fk_processo_maquina FOREIGN KEY ("id_maquina") REFERENCES "DIM_MAQUINA" ("id_maquina");
ALTER TABLE "FAT_PERDAS" ADD CONSTRAINT fk_perdas_maquina FOREIGN KEY ("id_maquina") REFERENCES "DIM_MAQUINA" ("id_maquina");
ALTER TABLE "FAT_ACAO_MELHORIA" ADD CONSTRAINT fk_acao_maquina FOREIGN KEY ("id_maquina") REFERENCES "DIM_MAQUINA" ("id_maquina");
ALTER TABLE "FAT_ACAO_MELHORIA" ADD CONSTRAINT fk_acao_causa FOREIGN KEY ("id_causa") REFERENCES "DIM_CAUSA_RAIZ" ("id_causa");
CREATE INDEX idx_manut_maquina_data ON "FAT_MANUTENCAO" ("id_maquina","data_inicio");
CREATE INDEX idx_prod_maquina_data ON "FAT_PRODUCAO" ("id_maquina","data");
CREATE INDEX idx_energia_maquina_data ON "FAT_ENERGIA" ("id_maquina","data");

